  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute;
  left: 12px; top: -40px;
  background: var(--bg-3);
  color: var(--text);
  padding: 8px 12px;
  border-radius: 8px;
  text-decoration: none;
  z-index: 1000;
}
.skip-link:focus { top: 12px; outline: 2px solid var(--focus); }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 6px;
}

.site-header {
  border-bottom: 1px solid var(--border);
  background: rgba(11, 13, 18, 0.6);
  backdrop-filter: blur(8px);
  position: sticky; top: 0; z-index: 10;
}
.site-header nav {
  max-width: 1080px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.brand {
  font-weight: 700;
  letter-spacing: 0.2px;
  color: var(--text);
  text-decoration: none;
  font-size: 1.05rem;
}
.brand span { color: var(--accent); }
.nav-list {
  list-style: none;
  display: flex;
  gap: 8px;
  margin: 0; padding: 0;
}
.nav-list a {
  color: var(--text-muted);
  text-decoration: none;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 0.95rem;
}
.nav-list a:hover { color: var(--text); background: var(--bg-2); }
.nav-list a[aria-current="page"] {
  color: var(--text);
  background: var(--bg-2);
  border: 1px solid var(--border);
}

.preview {
  max-width: 1080px;
  margin: 0 auto;
  padding: 32px 24px 64px;
}
.preview__title {
  font-size: clamp(1.5rem, 2.4vw, 2rem);
  margin: 0 0 6px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.preview__meta {
  margin: 0 0 24px;
  color: var(--text-muted);
  font-size: 0.92rem;
}

.preview__figure {
  margin: 0 0 20px;
  background: var(--bg-1);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}
.preview__image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 70vh;
  object-fit: cover;
  background: #000;
}
.preview__caption {
  padding: 12px 16px;
  color: var(--text-muted);
  font-size: 0.9rem;
  border-top: 1px solid var(--border);
  background: var(--bg-2);
}

.preview__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.btn {
  --btn-bg: var(--bg-2);
  --btn-bd: var(--border-strong);
  --btn-fg: var(--text);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  font: inherit;
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--btn-fg);
  background: var(--btn-bg);
  border: 1px solid var(--btn-bd);
  border-radius: 10px;
  cursor: pointer;
  transition: background-color .15s ease, border-color .15s ease, transform .05s ease;
}
.btn:hover { background: var(--bg-3); }
.btn:active { transform: translateY(1px); }

.btn--ghost { --btn-bg: transparent; --btn-bd: var(--border); --btn-fg: var(--text); }
.btn--ghost:hover { background: var(--bg-2); border-color: var(--border-strong); }

.btn--danger {
  --btn-bg: var(--danger-bg);
  --btn-bd: #5a2230;
  --btn-fg: var(--danger-strong);
}
.btn--danger:hover {
  background: #4a1d27;
  border-color: #76293a;
  color: #ffc4cc;
}

/* Forced colors: keep buttons readable */
@media (forced-colors: active) {
  .btn { border: 1px solid ButtonBorder; background: ButtonFace; color: ButtonText; }
  .btn--danger { color: ButtonText; }
  :focus-visible { outline: 2px solid Highlight; }
}

/* Dialog */
.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 10, 0.65);
  backdrop-filter: blur(4px);
  display: grid;
  place-items: center;
  padding: 20px;
  z-index: 100;
  animation: fade-in .12s ease-out;
}
.dialog-backdrop[hidden] { display: none; }

.dialog {
  position: relative;
  width: min(440px, 100%);
  background: linear-gradient(180deg, var(--bg-2), var(--bg-1));
  color: var(--text);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  box-shadow: var(--shadow);
  padding: 22px 22px 18px;
  animation: pop-in .14s ease-out;
}

.dialog__header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 8px;
  padding-right: 32px; /* avoid close button */
}
.dialog__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px; height: 38px;
  border-radius: 10px;
  background: var(--danger-bg);
  color: var(--danger-strong);
  border: 1px solid #5a2230;
  flex: 0 0 auto;
}
.dialog__title {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -0.005em;
}
.dialog__desc {
  margin: 6px 0 18px;
  color: var(--text-muted);
  font-size: 0.95rem;
}
.dialog__actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.dialog__close {
  position: absolute;
  top: 10px; right: 10px;
  width: 32px; height: 32px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent;
  color: var(--text-muted);
  border: 1px solid transparent;
  border-radius: 8px;
  cursor: pointer;
}
.dialog__close:hover { color: var(--text); background: var(--bg-3); border-color: var(--border); }

@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }
@keyframes pop-in {
  from { opacity: 0; transform: translateY(6px) scale(.98); }
  to   { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog { animation: none; }
  .btn { transition: none; }
}

/* Reflow: stack actions on narrow viewports */
@media (max-width: 380px) {
  .dialog__actions { flex-direction: column-reverse; align-items: stretch; }
  .dialog__actions .btn { justify-content: center; }
}
